ownProperties.type:
{
    enable: boolean;
    trigger?: "click" | "hover" | undefined;
    effect: "adjacency" | "related" | "self";
} | undefined

ownProperties.originalType:
{
    /** 是否开启交互 */
    enable: boolean;
    /**
     * 交互触发类型
     * 默认为‘click'
     */
    trigger?: 'click' | 'hover';
    /**桑基图提供3种在节点上的交互联动效果
     * self: 仅高亮当前节点。
     * adjacency: 高亮当前节点上下游节点和关联的边，淡化其它图形元素。
     * related： 高亮与当前节点相关的整条路径上的节点和边，淡化其它图形元素。 */
    effect: 'self' | 'adjacency' | 'related';
  }

ownProperties.description:
每个节点的宽度，支持三种取值
1. 百分比字符串，例如：{ nodeWidth: '12%' }
2. 以'px'为单位的简单数字，eg: { nodeWidth: 20 }
3. function，通过自定义计算指定nodeWidth

